sourcesContent:
.contact {
  background: var(--bg-soft);
  border-top: 1px solid var(--border);
}

.contact-card {
  display: grid;
  grid-template-columns: 1fr 1.1fr;
  border: 1px solid var(--border-gold);
  border-radius: calc(var(--radius) + 6px);
  overflow: hidden;
  background:
    radial-gradient(90% 120% at 0% 0%, rgba(201, 169, 98, 0.09) 0%, transparent 55%),
    var(--surface);
}

.contact-info {
  padding: clamp(32px, 5vw, 60px);
}

.contact-cta {
  margin-top: 34px;
}

.contact-address {
  margin-top: 34px;
  padding-top: 26px;
  border-top: 1px solid var(--border);
  font-style: normal;
}

.contact-address-row {
  display: flex;
  align-items: flex-start;
  gap: 11px;
  font-size: 14px;
  line-height: 1.6;
  color: var(--text-muted);
}

.contact-address-row svg {
  flex: none;
  margin-top: 3px;
  color: var(--gold);
}

.contact-maps-link {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  margin-top: 12px;
  margin-left: 28px;
  font-size: 13.5px;
  font-weight: 600;
  color: var(--gold-soft);
  transition: color 0.2s ease;
}

.contact-maps-link:hover {
  color: var(--gold);
}

.contact-map {
  position: relative;
  min-height: 380px;
}

.contact-map iframe {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  border: 0;
  filter: grayscale(1) invert(0.92) contrast(0.9) brightness(0.9);
}

@media (max-width: 900px) {
  .contact-card {
    grid-template-columns: 1fr;
  }

  .contact-map {
    min-height: 300px;
    order: -1;
  }
}
